(7043823, 1069898, 159377, '<td valign="top">yep, he''s holding a fork in the road. nice composition. need greater separation of the subject from the background. the contrast looks pretty good - maybe by lightly blurring the background. a different perspective could also make the "S" in the road more interesting</td>', 'yep, he''s holding a fork in the road. nice composition. need greater separation of the subject from the background. the contrast looks pretty good - maybe by lightly blurring the background. a different perspective could also make the "S" in the road more interesting', '2013-05-27 11:54:37.000000', NULL, 1),
(7043824, 1070124, 159377, '<td valign="top">nice contrasts in the background. the reflections on the forks are a distraction - tough to control. one fork may have been sufficient - probably just the middle one.</td>', 'nice contrasts in the background. the reflections on the forks are a distraction - tough to control. one fork may have been sufficient - probably just the middle one.', '2013-05-27 11:57:15.000000', NULL, 1),
